let strip_whitespace s =
  String.to_seq s
  |> Seq.filter (function
    | ' '
    | '\t'
    | '\n'
    | '\r' ->
        false
    | _ -> true)
  |> String.of_seq

let make_files alist : (string, string) Hashtbl.t =
  let tbl = Hashtbl.create 16 in
  List.iter (fun (k, v) -> Hashtbl.replace tbl k v) alist;
  tbl








let with_test_db (_files : (string, string) Hashtbl.t) f =
  Sqlite_util.Connect.with_connection Memory (fun db ->
      Text.create_tables db;
      f db)




let test_source : App_types.Text.source =
  match App_types.Source.of_string_opt "files:test" with
  | Some s -> s
  | None -> assert false

let with_declared_test_db files f =
  with_test_db files (fun db ->
      Text.put_source db test_source;
      f db)




let source (files : (string, string) Hashtbl.t) path : Util.Text_source.t =
  { name = path; contents = Hashtbl.find files path }

let source_doc path : App_types.Src_doc.t =
  App_types.Src_doc.of_source_doc_exn
    { T.source = test_source; locator = path }

let check_range ~msg (expected : T.range) (actual : T.range) =
  Testo.check ~msg
    (Testo.tuple2 Testo.int Testo.int)
    (expected.start, expected.end_)
    (actual.start, actual.end_)

let find_by_id anchors id =
  List.find_opt (fun (a : Text.anchor) -> a.anchor_id = id) anchors




let check_contents_matches_range ~msg document (a : Text.anchor) =
  Testo.check
    ~msg:(msg ^ ": length matches range")
    Testo.int
    (a.range.end_ - a.range.start)
    (String.length a.raw_contents);
  Testo.check
    ~msg:(msg ^ ": bytes match the document at range")
    Testo.string
    (String.sub document a.range.start (a.range.end_ - a.range.start))
    a.raw_contents

